Q: Uploading image - data appears like this &quot;���&quot;�!1A&quot;Qaq��2��B�#&quot; and image is blank - Next.js application upload to DigitalOcean Spaces / AWS S3 A: <p>Figured it out. I wasn't encoding the image properly in my Next.js serverless backend.</p>
<p>First, on the front end, I made my fetch request like this. It's important to put it in the &quot;form&quot; format for the next step in the backend:</p>
<pre><code>async function handleProfileImageUpload(e) {
    const file = e.target.files[0];
    const formData = new FormData();
    formData.append('file', file);

    // CHECK THAT THE FILE IS PROPER FORMAT (size, type, etc)

    let url = false;
    await fetch(`/api/image/profileUpload`, {
      method: 'POST',
      body: formData,
      'Content-Type': 'image/jpg',
    })
}
</code></pre>
<p>There were several components that helped me finally do this on the backend, so I am just going to post the code I ended up with. Here's the API route:</p>
<pre><code>import AWS from 'aws-sdk';
import formidable from 'formidable-serverless';
import fs from 'fs';

export const config = {
  api: {
    bodyParser: false,
  },
};

export default async (req, res) =&gt; {

  // create S3 instance with credentials
  const s3 = new AWS.S3({
    endpoint: new AWS.Endpoint('nyc3.digitaloceanspaces.com'),
    accessKeyId: process.env.SPACES_KEY,
    secretAccessKey: process.env.SPACES_SECRET,
    region: 'nyc3',
  });

  // parse request to readable form
  const form = new formidable.IncomingForm();
  form.parse(req, async (err, fields, files) =&gt; {
    // Account for parsing errors
    if (err) return res.status(500);
    // Read file
    const file = fs.readFileSync(files.file.path);
    // Upload the file
    s3.upload({ 
      // params
      Bucket: process.env.SPACES_BUCKET,
      ACL: &quot;public-read&quot;,
      Key: 'something',
      Body: file,
      ContentType: &quot;image/jpeg&quot;,
    })
    .send((err, data) =&gt; {
      if (err) {
        console.log('err',err)
        return res.status(500);
      };
      if (data) {
        console.log('data',data)

        return res.json({
          url:  data.Location,
        });
      };
    });
  });
};
</code></pre>
